17	package org.apache.camel.component.langchain4j.agent;
18	
19	import java.io.File;
20	import java.io.IOException;
21	import java.io.InputStream;
22	import java.net.URLConnection;
23	import java.nio.file.Files;
24	import java.util.Base64;
25	
26	import dev.langchain4j.data.audio.Audio;
27	import dev.langchain4j.data.image.Image;
28	import dev.langchain4j.data.message.AudioContent;
29	import dev.langchain4j.data.message.Content;
30	import dev.langchain4j.data.message.ImageContent;
31	import dev.langchain4j.data.message.PdfFileContent;
32	import dev.langchain4j.data.message.TextContent;
33	import dev.langchain4j.data.message.VideoContent;
34	import dev.langchain4j.data.pdf.PdfFile;
35	import dev.langchain4j.data.video.Video;
36	import org.apache.camel.Converter;
37	import org.apache.camel.Exchange;
38	import org.apache.camel.Message;
39	import org.apache.camel.WrappedFile;
40	import org.apache.camel.component.langchain4j.agent.api.AiAgentBody;
41	import org.slf4j.Logger;
42	import org.slf4j.LoggerFactory;
43	
44	import static org.apache.camel.component.langchain4j.agent.api.Headers.MEDIA_TYPE;
45	import static org.apache.camel.component.langchain4j.agent.api.Headers.MEMORY_ID;
46	import static org.apache.camel.component.langchain4j.agent.api.Headers.SYSTEM_MESSAGE;
47	import static org.apache.camel.component.langchain4j.agent.api.Headers.USER_MESSAGE;
48	
49	/**
50	 * Type converters for the LangChain4j Agent component.
51	 * <p>
52	 * Provides automatic conversion from various input types to {@link AiAgentBody} with appropriate LangChain4j
53	 * {@link Content} types based on the MIME type.
54	 * </p>
55	 * <p>
56	 * Supported input types:
57	 * </p>
58	 * <ul>
59	 * <li>{@link WrappedFile} - from file, ftp, sftp components</li>
60	 * <li>{@code byte[]} - from aws2-s3, azure-storage-blob, and other cloud components</li>
61	 * <li>{@link InputStream} - from various streaming components</li>
62	 * </ul>
63	 * <p>
64	 * <strong>Note:</strong> For {@code byte[]} and {@link InputStream}, the MIME type must be provided via the
65	 * {@code CamelLangChain4jAgentMediaType} header or a component-specific content type header.
66	 * </p>
67	 */
68	@Converter(generateLoader = true)
69	public final class LangChain4jAgentConverter {
70	
71	    private static final Logger LOG = LoggerFactory.getLogger(LangChain4jAgentConverter.class);
72	
73	    private LangChain4jAgentConverter() {
74	    }
75	
76	    /**
77	     * Converts a {@link WrappedFile} to an {@link AiAgentBody} with the appropriate {@link Content} type.
78	     * <p>
79	     * The conversion uses the following headers from the exchange:
80	     * </p>
81	     * <ul>
82	     * <li>{@code CamelLangChain4jAgentUserMessage} - The text message to accompany the file content</li>
83	     * <li>{@code CamelLangChain4jAgentSystemMessage} - Optional system message for the AI agent</li>
84	     * <li>{@code CamelLangChain4jAgentMemoryId} - Optional memory ID for stateful conversations</li>
85	     * <li>{@code CamelLangChain4jAgentMediaType} - Optional MIME type override (highest priority)</li>
86	     * <li>{@code Exchange.FILE_CONTENT_TYPE} - MIME type from file components (second priority)</li>
87	     * </ul>
88	     * <p>
89	     * If no MIME type header is found, the type is auto-detected from the file extension.
90	     * </p>
91	     *
92	     * @param  wrappedFile              the wrapped file from file-based components (file, ftp, sftp, etc.)
93	     * @param  exchange                 the Camel exchange containing headers
94	     * @return                          an AiAgentBody with the appropriate Content type
95	     * @throws IllegalArgumentException if the file cannot be read or the MIME type is unsupported
96	     */
97	    @Converter
98	    public static AiAgentBody<?> toAiAgentBody(WrappedFile<?> wrappedFile, Exchange exchange) {
99	        Object fileObj = wrappedFile.getFile();
100	        if (fileObj == null) {
101	            throw new IllegalArgumentException("WrappedFile contains null file");
102	        }
103	        if (!(fileObj instanceof File)) {
104	            throw new IllegalArgumentException(
105	                    "WrappedFile must contain a java.io.File instance, got: " + fileObj.getClass().getName());
106	        }
107	
108	        File file = (File) fileObj;
109	        String mimeType = detectMimeType(file, exchange);
110	        byte[] fileData = readFileBytes(file);
111	        Content content = createContent(fileData, mimeType);
112	
113	        return buildAiAgentBody(exchange, content, "");
114	    }
115	
116	    /**
117	     * Converts a {@code byte[]} to an {@link AiAgentBody} with the appropriate {@link Content} type.
118	     * <p>
119	     * This converter is useful for cloud storage components like aws2-s3, azure-storage-blob, etc. that return file
120	     * content as byte arrays.
121	     * </p>
122	     * <p>
123	     * <strong>Important:</strong> The MIME type must be provided via headers since it cannot be auto-detected from byte
124	     * arrays. Supported headers (in priority order):
125	     * </p>
126	     * <ul>
127	     * <li>{@code CamelLangChain4jAgentMediaType} header (highest priority)</li>
128	     * <li>{@code CamelAwsS3ContentType} header (from AWS S3)</li>
129	     * <li>{@code CamelAzureStorageBlobContentType} header (from Azure Blob Storage)</li>
130	     * <li>{@code CamelAzureStorageDataLakeContentType} header (from Azure Data Lake Storage)</li>
131	     * <li>{@code CamelGoogleCloudStorageContentType} header (from Google Cloud Storage)</li>
132	     * <li>{@code CamelMinioContentType} header (from Minio)</li>
133	     * <li>{@code CamelIBMCOSContentType} header (from IBM Cloud Object Storage)</li>
134	     * <li>{@code Content-Type} header</li>
135	     * <li>{@code CamelFileContentType} header (from file components)</li>
136	     * </ul>
137	     *
138	     * @param  data                     the file content as a byte array
139	     * @param  exchange                 the Camel exchange containing headers
140	     * @return                          an AiAgentBody with the appropriate Content type
141	     * @throws IllegalArgumentException if the MIME type is not provided or is unsupported
142	     */
143	    @Converter
144	    public static AiAgentBody<?> byteArrayToAiAgentBody(byte[] data, Exchange exchange) {
145	        String mimeType = detectMimeTypeFromHeaders(exchange);
146	        Content content = createContent(data, mimeType);
147	
148	        return buildAiAgentBody(exchange, content, "");
149	    }
150	
151	    /**
152	     * Converts an {@link InputStream} to an {@link AiAgentBody} with the appropriate {@link Content} type.
153	     * <p>
154	     * This converter is useful for streaming components that return file content as input streams.
155	     * </p>
156	     * <p>
157	     * <strong>Important:</strong> The MIME type must be provided via headers since it cannot be auto-detected from
158	     * streams.
159	     * </p>
160	     *
161	     * @param  inputStream              the file content as an input stream
162	     * @param  exchange                 the Camel exchange containing headers
163	     * @return                          an AiAgentBody with the appropriate Content type
164	     * @throws IllegalArgumentException if the stream cannot be read or the MIME type is not provided/unsupported
165	     */
166	    @Converter
167	    public static AiAgentBody<?> inputStreamToAiAgentBody(InputStream inputStream, Exchange exchange) {
168	        try {
169	            byte[] data = inputStream.readAllBytes();
170	            return byteArrayToAiAgentBody(data, exchange);
171	        } catch (IOException e) {
172	            throw new IllegalArgumentException("Failed to read input stream", e);
173	        }
174	    }
175	
176	    /**
177	     * Converts a {@link String} to an {@link AiAgentBody} with the appropriate {@link Content} type.
178	     * <p>
179	     * This converter is useful for the text components that return Text Body.
180	     * </p>
181	     *
182	     * @param  text     String as message
183	     * @param  exchange the Camel exchange containing headers
184	     * @return          an AiAgentBody with the appropriate Content type
185	     */
186	    @Converter
187	    public static AiAgentBody<?> textToAiAgentBody(String text, Exchange exchange) {
188	        return buildAiAgentBody(exchange, null, text);
189	    }
190	
191	    /**
192	     * Creates the appropriate LangChain4j Content object based on the MIME type.
193	     */
194	    static Content createContent(byte[] data, String mimeType) {
195	        String base64Data = Base64.getEncoder().encodeToString(data);
196	
197	        if (mimeType.startsWith("image/")) {
198	            Image image = Image.builder()
199	                    .base64Data(base64Data)
200	                    .mimeType(mimeType)
201	                    .build();
202	            return ImageContent.from(image);
203	        } else if (mimeType.startsWith("audio/")) {
204	            Audio audio = Audio.builder()
205	                    .base64Data(base64Data)
206	                    .mimeType(mimeType)
207	                    .build();
208	            return AudioContent.from(audio);
209	        } else if (mimeType.startsWith("video/")) {
210	            Video video = Video.builder()
211	                    .base64Data(base64Data)
212	                    .mimeType(mimeType)
213	                    .build();
214	            return VideoContent.from(video);
215	        } else if ("application/pdf".equals(mimeType)) {
216	            PdfFile pdfFile = PdfFile.builder()
217	                    .base64Data(base64Data)
218	                    .build();
219	            return PdfFileContent.from(pdfFile);
220	        } else if (mimeType.startsWith("text/")) {
221	            return TextContent.from(new String(data));
222	        } else {
223	            throw new IllegalArgumentException(
224	                    "Unsupported MIME type: " + mimeType
225	                                               + ". Supported types: image/*, audio/*, video/*, application/pdf, text/*");
226	        }
227	    }
228	
229	    /**
230	     * Detects the MIME type from headers or file extension.
231	     * <p>
232	     * Priority:
233	     * </p>
234	     * <ol>
235	     * <li>CamelLangChain4jAgentMediaType header (highest priority)</li>
236	     * <li>Exchange.FILE_CONTENT_TYPE header (from file components)</li>
237	     * <li>Auto-detection from file extension</li>
238	     * </ol>
239	     */
240	    private static String detectMimeType(File file, Exchange exchange) {
241	        // Check agent-specific header first (highest priority)
242	        String mediaType = exchange.getMessage().getHeader(MEDIA_TYPE, String.class);
243	        if (mediaType != null) {
244	            return mediaType;
245	        }
246	
247	        // Check file component's content type header
248	        String fileContentType = exchange.getMessage().getHeader(Exchange.FILE_CONTENT_TYPE, String.class);
249	        if (fileContentType != null) {
250	            return fileContentType;
251	        }
252	
253	        // Auto-detect from file extension
254	        return detectMimeTypeFromExtension(file.getName());
255	    }
256	
257	    /**
258	     * Detects the MIME type from headers only (for byte[] and InputStream where file extension is not available).
259	     * <p>
260	     * Priority:
261	     * </p>
262	     * <ol>
263	     * <li>CamelLangChain4jAgentMediaType header (highest priority)</li>
264	     * <li>Cloud storage component headers (AWS S3, Azure Blob, Google Cloud, Minio, IBM COS)</li>
265	     * <li>Exchange.CONTENT_TYPE header</li>
266	     * <li>Exchange.FILE_CONTENT_TYPE header</li>
267	     * </ol>
268	     *
269	     * @throws IllegalArgumentException if no MIME type header is found
270	     */
271	    private static String detectMimeTypeFromHeaders(Exchange exchange) {
272	        // Check agent-specific header first (highest priority)
273	        Message message = exchange.getMessage();
274	
275	        String mediaType = message.getHeader(MEDIA_TYPE, String.class);
276	        if (mediaType != null) {
277	            return normalizeContentType(mediaType);
278	        }
279	        // Cloud storage component content type headers
280	        String[] cloudContentTypeHeaders = {
281	                "CamelAwsS3ContentType",                  // AWS S3
282	                "CamelAzureStorageBlobContentType",       // Azure Blob Storage
283	                "CamelAzureStorageDataLakeContentType",   // Azure Data Lake Storage
284	                "CamelGoogleCloudStorageContentType",     // Google Cloud Storage
285	                "CamelMinioContentType",                  // Minio (S3-compatible)
286	                "CamelIBMCOSContentType"                  // IBM Cloud Object Storage
287	        };
288	
289	        for (String header : cloudContentTypeHeaders) {
290	            String cloudContentType = message.getHeader(header, String.class);
291	            if (cloudContentType != null) {
292	                return normalizeContentType(cloudContentType);
293	            }
294	        }
295	        // Check standard content type header
296	        String contentType = message.getHeader(Exchange.CONTENT_TYPE, String.class);
297	        if (contentType != null) {
298	            return normalizeContentType(contentType);
299	        }
300	        // Check file component's content type header
301	        String fileContentType = message.getHeader(Exchange.FILE_CONTENT_TYPE, String.class);
302	        if (fileContentType != null) {
303	            return normalizeContentType(fileContentType);
304	        }
305	
306	        String fileName = message.getHeader(Exchange.FILE_NAME, String.class);
307	        if (fileName != null) {
308	            String mime = URLConnection.guessContentTypeFromName(fileName);
309	            if (mime != null) {
310	                return normalizeContentType(mime);
311	            }
312	        }
313	
314	        throw new IllegalArgumentException(
315	                "MIME type is required for byte[] or InputStream input. "
316	                                           + "Please set the CamelLangChain4jAgentMediaType header.");
317	    }
318	
319	    /**
320	     * Normalizes a content type by removing charset and other parameters.
321	     * <p>
322	     * For example: "text/html; charset=utf-8" becomes "text/html"
323	     * </p>
324	     */
325	    private static String normalizeContentType(String contentType) {
326	        int semicolon = contentType.indexOf(';');
327	        return semicolon > 0 ? contentType.substring(0, semicolon).trim() : contentType;
328	    }
329	
330	    /**
331	     * Detects the MIME type from the file extension.
332	     */
333	    private static String detectMimeTypeFromExtension(String fileName) {
334	        String lowerName = fileName.toLowerCase();
335	
336	        // Image formats
337	        if (lowerName.endsWith(".png")) {
338	            return "image/png";
339	        } else if (lowerName.endsWith(".jpg") || lowerName.endsWith(".jpeg")) {
340	            return "image/jpeg";
341	        } else if (lowerName.endsWith(".gif")) {
342	            return "image/gif";
343	        } else if (lowerName.endsWith(".webp")) {
344	            return "image/webp";
345	        } else if (lowerName.endsWith(".bmp")) {
346	            return "image/bmp";
347	        } else if (lowerName.endsWith(".tiff") || lowerName.endsWith(".tif")) {
348	            return "image/tiff";
349	        } else if (lowerName.endsWith(".svg")) {
350	            return "image/svg+xml";
351	        }
352	        // Video formats
353	        else if (lowerName.endsWith(".mp4")) {
354	            return "video/mp4";
355	        } else if (lowerName.endsWith(".webm")) {
356	            return "video/webm";
357	        } else if (lowerName.endsWith(".mov")) {
358	            return "video/quicktime";
359	        } else if (lowerName.endsWith(".mkv")) {
360	            return "video/x-matroska";
361	        } else if (lowerName.endsWith(".avi")) {
362	            return "video/x-msvideo";
363	        }
364	        // Audio formats
365	        else if (lowerName.endsWith(".wav")) {
366	            return "audio/wav";
367	        } else if (lowerName.endsWith(".mp3")) {
368	            return "audio/mpeg";
369	        } else if (lowerName.endsWith(".ogg")) {
370	            return "audio/ogg";
371	        } else if (lowerName.endsWith(".m4a")) {
372	            return "audio/mp4";
373	        } else if (lowerName.endsWith(".flac")) {
374	            return "audio/flac";
375	        }
376	        // Document formats
377	        else if (lowerName.endsWith(".pdf")) {
378	            return "application/pdf";
379	        }
380	        // Text formats
381	        else if (lowerName.endsWith(".txt")) {
382	            return "text/plain";
383	        } else if (lowerName.endsWith(".csv")) {
384	            return "text/csv";
385	        } else if (lowerName.endsWith(".html") || lowerName.endsWith(".htm")) {
386	            return "text/html";
387	        } else if (lowerName.endsWith(".md")) {
388	            return "text/markdown";
389	        } else if (lowerName.endsWith(".xml")) {
390	            return "text/xml";
391	        } else if (lowerName.endsWith(".json")) {
392	            return "application/json";
393	        }
394	
395	        LOG.warn("Could not detect MIME type from file extension: {}. Please set the CamelLangChain4jAgentMediaType header.",
396	                fileName);
397	        throw new IllegalArgumentException(
398	                "Cannot determine MIME type for file: " + fileName
399	                                           + ". Please set the CamelLangChain4jAgentMediaType header.");
400	    }
401	
402	    /**
403	     * Reads the file content as a byte array.
404	     */
405	    private static byte[] readFileBytes(File file) {
406	        try {
407	            return Files.readAllBytes(file.toPath());
408	        } catch (IOException e) {
409	            throw new IllegalArgumentException("Failed to read file: " + file.getAbsolutePath(), e);
410	        }
411	    }
412	
413	    /**
414	     * Utility method to build agent body.
415	     *
416	     * @param  exchange           the Camel exchange containing message headers
417	     * @param  content            the LangChain4j content to attach to the agent body
418	     * @param  defaultUserMessage the fallback user message if the corresponding header is absent
419	     * @return                    a fully populated {@link AiAgentBody} instance
420	     * @param  <T>                the type of LangChain4j {@link Content}
421	     */
422	    private static <
423	            T extends Content> AiAgentBody<T> buildAiAgentBody(Exchange exchange, T content, String defaultUserMessage) {
424	
425	        Message message = exchange.getMessage();
426	
427	        String userMessage = message.getHeader(USER_MESSAGE, String.class);
428	        String systemMessage = message.getHeader(SYSTEM_MESSAGE, String.class);
429	        Object memoryId = message.getHeader(MEMORY_ID);
430	
431	        AiAgentBody<T> body = new AiAgentBody<>();
432	        body.setUserMessage(userMessage != null ? userMessage : defaultUserMessage);
433	        body.setSystemMessage(systemMessage);
434	        body.setMemoryId(memoryId);
435	        body.setContent(content);
436	
437	        return body;
438	    }
439	}
