@Converter
public static AiAgentBody<?> toAiAgentBody(WrappedFile<?> wrappedFile, Exchange exchange) {
    Object fileObj = wrappedFile.getFile();
    if (fileObj == null) {
        throw new IllegalArgumentException("WrappedFile contains null file");
    }

    if (fileObj instanceof File) {
        File file = (File) fileObj;
        String mimeType = detectMimeType(file, exchange);
        byte[] fileData = readFileBytes(file);
        Content content = createContent(fileData, mimeType);
        return buildAiAgentBody(exchange, content, "");
    }

    // Remote file (FTP, SFTP, etc.): the underlying handle is not a java.io.File.
    // Read the content from the body that the transport component has already buffered.
    Object body = wrappedFile.getBody();
    if (body == null) {
        throw new IllegalArgumentException(
                "WrappedFile has no body and does not contain a java.io.File; cannot read content");
    }

    byte[] data;
    if (body instanceof byte[]) {
        data = (byte[]) body;
    } else if (body instanceof InputStream) {
        try {
            data = ((InputStream) body).readAllBytes();
        } catch (IOException e) {
            throw new IllegalArgumentException("Failed to read WrappedFile body stream", e);
        }
    } else {
        throw new IllegalArgumentException("Unsupported WrappedFile body type: " + body.getClass().getName());
    }

    String mimeType = detectMimeTypeFromHeaders(exchange);
    Content content = createContent(data, mimeType);
    return buildAiAgentBody(exchange, content, "");
}

